1112	// ---- 结构检查：固定字段名逐字匹配 + 重复键拒绝 ----
1113	
1114	// schemaKind 是状态文件 JSON 在某一层的形状类别。
1115	type schemaKind int
1116	
1117	const (
1118		kindAny     schemaKind = iota // 叶子值：结构检查不深入，类型由解码器核对
1119		kindObject                    // 固定字段对象：键必须与保存格式的字段名逐字一致
1120		kindMap                       // 业务编号表：键是自由文本（账户名、提案编号）
1121		kindArray                     // 数组
1122		kindString                    // 叶子：必须是 JSON 字符串
1123		kindBoolean                   // 叶子：必须是 JSON 布尔值（不接受字符串/数字/null）
1124		kindInteger                   // 叶子：必须是 int64 范围内的 JSON 整数（不接受小数/指数/字符串/null）
1125	)
1126	
1127	// schemaNode 描述状态文件某一层允许的形状。整棵树由 storedState 的 json tag
1128	// 反射生成，字段名集合因此永远与保存格式一致，不会随结构演进而漂移。
1129	type schemaNode struct {
1130		kind   schemaKind
1131		fields map[string]*schemaNode // kindObject：字段名 → 值的形状
1132		elem   *schemaNode            // kindMap/kindArray：值/元素的形状
1133	}
1134	
1135	// schemaOf 按 encoding/json 的字段名规则（json tag 优先，缺省用字段名）推导形状。
1136	func schemaOf(t reflect.Type) *schemaNode {
1137		for t.Kind() == reflect.Pointer {
1138			t = t.Elem()
1139		}
1140		switch t.Kind() {
1141		case reflect.Struct:
1142			node := &schemaNode{kind: kindObject, fields: map[string]*schemaNode{}}
1143			for i := 0; i < t.NumField(); i++ {
1144				f := t.Field(i)
1145				if f.PkgPath != "" { // 未导出字段不参与 JSON
1146					continue
1147				}
1148				name := f.Name
1149				if tag, ok := f.Tag.Lookup("json"); ok {
1150					tagName, _, _ := strings.Cut(tag, ",")
1151					if tagName == "-" {
1152						continue
1153					}
1154					if tagName != "" {
1155						name = tagName
1156					}
1157				}
1158				node.fields[name] = schemaOf(f.Type)
1159			}
1160			return node
1161		case reflect.Map:
1162			return &schemaNode{kind: kindMap, elem: schemaOf(t.Elem())}
1163		case reflect.Slice, reflect.Array:
1164			return &schemaNode{kind: kindArray, elem: schemaOf(t.Elem())}
1165		case reflect.String:
1166			return &schemaNode{kind: kindString}
1167		case reflect.Bool:
1168			return &schemaNode{kind: kindBoolean}
1169		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
1170			reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
1171			return &schemaNode{kind: kindInteger}
1172		default:
1173			return &schemaNode{kind: kindAny}
1174		}
1175	}
1176	
1177	var storedStateSchema = schemaOf(reflect.TypeOf(storedState{}))
1178	
1179	func init() {
1180		// 票据的四个标量字段（representative/weight/support/voted_at）由
1181		// validateStoredBallot 逐票判定“缺失/空值/类型不符”，其错误原因需要带上
1182		// 提案编号、票据下标与字段名；因此结构扫描在这些叶子位置保持宽松（kindAny），
1183		// 不抢在解码器之前用不含票据定位的通用信息报错。
1184		ballotFields := storedStateSchema.fields["vote_proposals"].elem.fields["ballots"].elem.fields
1185		for _, name := range []string{"representative", "weight", "support", "voted_at"} {
1186			ballotFields[name].kind = kindAny
1187		}
1188		// 计票结果的两个权重字段（for_weight/against_weight）同理：缺失/空值/
1189		// 类型不符的判定需要带上提案编号，统一由 validateStoredTally 报错，
1190		// 结构扫描在这两个叶子位置保持宽松。tallied_at 保持严格整数叶子，
1191		// 其“不早于截止”的既有校验不变。
1192		tallyFields := storedStateSchema.fields["vote_proposals"].elem.fields["tally"].fields
1193		for _, name := range []string{"for_weight", "against_weight"} {
1194			tallyFields[name].kind = kindAny
1195		}
1196		// 凭据的 executed_at 同理：缺失/空值/类型不符/早于时间锁的判定需要带上
1197		// 提案编号与凭据位置，统一由 validateReceiptExecutedAt 报错，结构扫描在此
1198		// 叶子位置保持宽松。
1199		receiptFields := storedStateSchema.fields["receipts"].elem.fields
1200		receiptFields["executed_at"].kind = kindAny
1201		// 凭据的 order 同理：缺失/空值/类型不符/位置不符的判定需要带上提案编号与
1202		// 凭据位置，统一由 validateReceiptOrder 报错，结构扫描在此叶子位置保持宽松。
1203		receiptFields["order"].kind = kindAny
1204		// 凭据逐笔留痕的 index 同理：缺失/空值/类型不符/位置不符的判定需要带上
1205		// 提案编号与动作下标，统一由 validateReceiptActionIndex 报错，结构扫描在
1206		// 此叶子位置保持宽松。
1207		receiptFields["actions"].elem.fields["index"].kind = kindAny
1208		// 凭据逐笔留痕的四个余额字段（treasury/recipient 的 before/after）同理：
1209		// 缺失/空值/类型不符的判定需要带上提案编号、动作下标与所在侧，统一由
1210		// validateReceiptActionBalances 报错，结构扫描在这些叶子位置保持宽松。
1211		actionFields := receiptFields["actions"].elem.fields
1212		for _, side := range []string{"treasury", "recipient"} {
1213			balanceFields := actionFields[side].fields
1214			balanceFields["before"].kind = kindAny
1215			balanceFields["after"].kind = kindAny
1216		}
1217	}
1218	
1219	// scanFrame 是结构扫描的栈帧。
1220	type scanFrame struct {
1221		node    *schemaNode
1222		isArray bool
1223		opaque  bool // 形状不符或叶子位置的容器：只配对括号，类型错误交给解码器报告
1224		seen    map[string]bool
1225		atValue bool // 对象帧：下一个待消费 token 是值而非键
1226		index   int  // 数组帧：下一个元素下标
1227		path    string
1228	}
1229	
1230	func peekFrame(stack []*scanFrame) *scanFrame {
1231		if len(stack) == 0 {
1232			return nil
1233		}
1234		return stack[len(stack)-1]
1235	}
1236	
1237	// checkStateStructure 在解码前逐 token 扫描状态文件：
1238	//   - 同一对象内键（按 JSON 解读后的字符串，转义拼写与普通拼写视为同一键）不得重复；
1239	//   - 固定字段对象的键必须与保存格式的字段名逐字一致：大小写变体（如 Treasury、
1240	//     Support）与未知字段一样拒绝，避免解码器的大小写折叠把两份值并入同一字段；
1241	//   - balances/proposals/vote_proposals 等业务编号表的键是自由文本，
1242	//     Audit 与 audit、GIP-1 与 gip-1 是不同账户/编号，不做字段名检查。
1243	//
1244	// 报错带有出问题的字段与所在记录的路径（如 vote_proposals["GIP-1"].ballots[0]），
1245	// 便于定位。字段顺序、缩进与合法转义不影响判定。
1246	func checkStateStructure(raw []byte) error {
1247		dec := json.NewDecoder(bytes.NewReader(raw))
1248		// UseNumber：数字 token 保留词面写法，整数叶子可据此精确判定 int64 范围，
1249		// 不被 float64 在 2^63 附近的舍入混淆（MaxInt64 与 MaxInt64+1 会折成同一浮点）。
1250		dec.UseNumber()
1251		var stack []*scanFrame
1252		// 对象帧读到键时，把该键对应值的形状与路径暂存于此，供紧随其后的值使用。
1253		pendingNode := storedStateSchema
1254		pendingPath := "state"
1255	
1256		// 一个值消费完毕：推进父帧的键/值位置或数组下标。
1257		finishValue := func() {
1258			top := peekFrame(stack)
1259			if top == nil || top.opaque {
1260				return
1261			}
1262			if top.isArray {
1263				top.index++
1264			} else {
1265				top.atValue = false
1266			}
1267		}
1268	
1269		for {
1270			tok, err := dec.Token()
1271			if err == io.EOF {
1272				if len(stack) != 0 {
1273					return errors.New("unterminated object or array")
1274				}
1275				return nil
1276			}
1277			if err != nil {
1278				return err
1279			}
1280	
1281			if top := peekFrame(stack); top != nil && top.opaque {
1282				// 不透明容器内不做字段检查，只配对括号。
1283				if d, ok := tok.(json.Delim); ok {
1284					if d == '{' || d == '[' {
1285						stack = append(stack, &scanFrame{opaque: true})
1286					} else {
1287						stack = stack[:len(stack)-1]
1288						finishValue()
1289					}
1290				}
1291				continue
1292			}
1293	
1294			if top := peekFrame(stack); top != nil && !top.isArray && !top.atValue {
1295				// 对象帧的键位置：闭括号或下一个键。
1296				if d, ok := tok.(json.Delim); ok {
1297					if d != '}' {
1298						return fmt.Errorf("unexpected %q inside object at %s", string(d), top.path)
1299					}
1300					stack = stack[:len(stack)-1]
1301					finishValue()
1302					continue
1303				}
1304				key, ok := tok.(string)
1305				if !ok {
1306					return errors.New("object key must be a string")
1307				}
1308				if top.seen[key] {
1309					return fmt.Errorf("duplicate key %q at %s", key, top.path)
1310				}
1311				top.seen[key] = true
1312				top.atValue = true
1313				switch top.node.kind {
1314				case kindObject:
1315					child, known := top.node.fields[key]
1316					if !known {
1317						return fmt.Errorf("unknown field %q at %s", key, top.path)
1318					}
1319					pendingNode = child
1320					pendingPath = top.path + "." + key
1321				case kindMap:
1322					// 业务编号是自由文本，大小写变体属于不同编号，不得拒绝或合并。
1323					pendingNode = top.node.elem
1324					pendingPath = top.path + "[" + strconv.Quote(key) + "]"
1325				}
1326				continue
1327			}
1328	
1329			// 值位置：对象键之后的值或数组元素。
1330			node := pendingNode
1331			path := pendingPath
1332			if top := peekFrame(stack); top != nil && top.isArray {
1333				node = top.node.elem
1334				path = top.path + "[" + strconv.Itoa(top.index) + "]"
1335			}
1336			if d, ok := tok.(json.Delim); ok {
1337				switch d {
1338				case '{', '[':
1339					frame := &scanFrame{isArray: d == '[', path: path}
1340					shapeOK := (d == '{' && (node.kind == kindObject || node.kind == kindMap)) ||
1341						(d == '[' && node.kind == kindArray)
1342					if !shapeOK {
1343						// 叶子位置出现容器或形状不符：跳过内容，类型错误由解码器报告。
1344						frame.opaque = true
1345					} else {
1346						frame.node = node
1347						if d == '{' {
1348							frame.seen = map[string]bool{}
1349						}
1350					}
1351					stack = append(stack, frame)
1352				default: // '}' 或 ']'：数组结束（对象的闭括号已在键位置处理）
1353					if len(stack) == 0 {
1354						return errors.New("unexpected closing delimiter")
1355					}
1356					stack = stack[:len(stack)-1]
1357					finishValue()
1358				}
1359				continue
1360			}
1361			// 标量值（含 null）：严格叶子必须与字段声明的 JSON 类型逐字一致，
1362			// null 不允许用来顶替字符串/布尔/整数。
1363			if err := checkLeafScalar(node, path, tok); err != nil {
1364				return err
1365			}
1366			finishValue()
1367		}
1368	}
