package main

import (
	"fmt"
	"unicode/utf8"
)

func check(raw []byte) error {
	n := len(raw)
	for i := 0; i < n; {
		if raw[i] != '"' { i++; continue }
		i++
		for i < n {
			c := raw[i]
			if c == '"' { i++; break }
			if c == '\\' { i += 2; continue }
			if c < 0x80 { i++; continue }
			_, size := utf8.DecodeRune(raw[i:])
			if size == 1 { return fmt.Errorf("bad utf8 at %d byte 0x%02X", i, c) }
			i += size
		}
	}
	return nil
}

func main() {
	doc := []byte("{\"gip-2\xff\":{\"id\":\"gip-2\xff\"}}")
	fmt.Printf("err: %v\n", check(doc))
}
