34			// 其后的原始 \u 转义，因此后面的高代理项仍需配对（配对版合法）。
35			[]byte(`{"a":"x�😀"}`),
36			// 非 BMP 字符直接以 UTF-8 出现在对象键（业务编号表键）中。
37			[]byte(`{"balances":{"😀":10}}`),
38		}
39		for i, doc := range valid {
40			if err := checkStrictStrings(doc); err != nil {
41				t.Fatalf("case %d valid document rejected: %v\n%s", i, err, doc)
42			}
43		}
44	}
45	
46	// TestStrictStringScannerRejectsInvalidUTF8：非法 UTF-8 字节序列必须被拒绝，
47	// 位置从文件开头按零计数，指向首个非法字节。
48	func TestStrictStringScannerRejectsInvalidUTF8(t *testing.T) {
49		cases := []struct {
50			name      string
51			doc       []byte
52			wantOff   int
53			where     string
54			wantInErr string
55		}{
56			{
57				name:      "impossible byte in value",
58				doc:       []byte("{\"a\":\"b\xff\"}"),
59				wantOff:   7,
60				wantInErr: "invalid UTF-8 encoding",
61			},
62			{
63				name:      "impossible byte in object key",
64				doc:       []byte("{\"k\xff\":1}"),
65				wantOff:   3,
66				wantInErr: "invalid UTF-8 encoding",
67			},
68			{
69				name:      "truncated multibyte sequence",
70				doc:       []byte("{\"a\":\"\xe4\xb8\"}"), // E4 B8 缺少尾字节
71				wantOff:   6,
72				wantInErr: "invalid UTF-8 encoding",
73			},
74			{
75				name:      "WTF-8 encoded surrogate",
76				doc:       []byte("{\"a\":\"\xed\xa0\x80\"}"), // U+D800 的 WTF-8 编码
77				wantOff:   6,
78				wantInErr: "invalid UTF-8 encoding",
79			},
80			{
81				name:      "overlong encoding",
82				doc:       []byte("{\"a\":\"\xc0\x80\"}"),
83				wantOff:   6,
84				wantInErr: "invalid UTF-8 encoding",
85			},
86			{
87				name:      "code point beyond U+10FFFF",
88				doc:       []byte("{\"a\":\"\xf4\x90\x80\x80\"}"),
89				wantOff:   6,
90				wantInErr: "invalid UTF-8 encoding",
91			},
92			{
93				name:      "stray continuation byte in map key",
94				doc:       []byte("{\"balances\":{\"\x80\":1}}"),
95				wantOff:   14,
96				wantInErr: "invalid UTF-8 encoding",
97			},
98		}
99		for _, tc := range cases {
100			t.Run(tc.name, func(t *testing.T) {
101				err := checkStrictStrings(tc.doc)
102				if err == nil {
103					t.Fatalf("document accepted, want corrupt: %q", tc.doc)
104				}
105				msg := err.Error()
106				if !strings.Contains(msg, tc.wantInErr) {
107					t.Fatalf("error %q does not mention %q", msg, tc.wantInErr)
108				}
109				want := "byte offset " + strconv.Itoa(tc.wantOff)
110				if !strings.Contains(msg, want) {
111					t.Fatalf("error %q does not contain %q", msg, want)
112				}
113			})
114		}
115	}
116	
117	// TestStrictStringScannerRejectsUnpairedSurrogates：\u 转义的高、低代理项
118	// 必须按正确次序成对出现；未配对时报错位置指向该转义开始的反斜杠。
119	func TestStrictStringScannerRejectsUnpairedSurrogates(t *testing.T) {
120		cases := []struct {
121			name      string
122			doc       []byte
123			wantOff   int
124			kind      string // "unpaired high surrogate" / "unpaired low surrogate"
125			wantEscape string
126		}{
127			{
128				name:       "lone high surrogate in value",
129				doc:        []byte(`{"a":"\uD800"}`),
130				wantOff:    6,
131				kind:       "unpaired high surrogate",
132				wantEscape: `\uD800`,
133			},
134			{
135				name:       "lone low surrogate in value",
136				doc:        []byte(`{"a":"\uDE00"}`),
137				wantOff:    6,
138				kind:       "unpaired low surrogate",
139				wantEscape: `\uDE00`,
140			},
141			{
142				name:       "lone surrogate in object key",
143				doc:        []byte(`{"\uD800":1}`),
144				wantOff:    2,
145				kind:       "unpaired high surrogate",
146				wantEscape: `\uD800`,
147			},
148			{
149				name:       "high surrogate followed by BMP escape",
150				doc:        []byte(`{"a":"\uD800A"}`),
151				wantOff:    6,
152				kind:       "unpaired high surrogate",
153				wantEscape: `\uD800`,
154			},
155			{
156				name:       "high surrogate followed by plain text",
157				doc:        []byte(`{"a":"\uD800x"}`),
158				wantOff:    6,
159				kind:       "unpaired high surrogate",
160				wantEscape: `\uD800`,
161			},
162			{
163				name:       "high surrogate at end of string",
164				doc:        []byte(`{"a":"\uD83D"}`),
165				wantOff:    6,
166				kind:       "unpaired high surrogate",
167				wantEscape: `\uD83D`,
168			},
169			{
170				name:       "two high surrogates",
171				doc:        []byte(`{"a":"😀\uD800"}`),
172				wantOff:    10,
173				kind:       "unpaired high surrogate",
174				wantEscape: `\uD800`,
175			},
176			{
177				name:       "extra low surrogate after a valid pair",
178				doc:        []byte(`{"a":"😀\uDE00"}`),
179				wantOff:    10,
180				kind:       "unpaired low surrogate",
181				wantEscape: `\uDE00`,
182			},
183			{
184				name:       "low surrogate uppercase hex digits",
185				doc:        []byte(`{"a":"\ude00"}`),
186				wantOff:    6,
187				kind:       "unpaired low surrogate",
188				wantEscape: `\uDE00`,
189			},
190		}
191		for _, tc := range cases {
192			t.Run(tc.name, func(t *testing.T) {
193				err := checkStrictStrings(tc.doc)
194				if err == nil {
195					t.Fatalf("document accepted, want corrupt: %s", tc.doc)
196				}
197				msg := err.Error()
198				if !strings.Contains(msg, tc.kind) {
199					t.Fatalf("error %q does not classify as %q", msg, tc.kind)
200				}
201				want := "byte offset " + strconv.Itoa(tc.wantOff)
202				if !strings.Contains(msg, want) {
203					t.Fatalf("error %q does not contain %q", msg, want)
204				}
205				if !strings.Contains(msg, tc.wantEscape) {
206					t.Fatalf("error %q does not quote escape %q", msg, tc.wantEscape)
207				}
208			})
209		}
210	}
211	
212	// TestStrictStringScannerEscapeSpellingsEquivalent：同一字符直接写出与采用
213	// 合法转义，扫描放行后交给 encoding/json 得到完全相同的字符串；两种拼写
214	// 若出现在同一对象中，结构扫描按解读后的键判为重复键。
215	func TestStrictStringScannerEscapeSpellingsEquivalent(t *testing.T) {
216		direct := []byte(`{"😀":1}`)
217		escaped := []byte(`{"😀":1}`)
218		if err := checkStrictStrings(direct); err != nil {
219			t.Fatalf("direct: %v", err)
220		}
221		if err := checkStrictStrings(escaped); err != nil {
222			t.Fatalf("escaped: %v", err)
223		}
224		var d, e map[string]int
225		if err := json.Unmarshal(direct, &d); err != nil {
226			t.Fatal(err)
227		}
228		if err := json.Unmarshal(escaped, &e); err != nil {
229			t.Fatal(err)
230		}
231		if len(d) != 1 || len(e) != 1 {
232			t.Fatalf("unexpected maps: %v %v", d, e)
233		}
234		for k := range d {
235			if _, ok := e[k]; !ok {
236				t.Fatalf("direct key %q not equal to escaped-spelled key", k)
237			}
238		}
239		// 两种拼写在同一对象中是同一个键：字符串扫描放行，结构扫描必须判重。
240		// 重复键检查放在 balances 业务编号表内（根对象按固定字段名校验形状）。
241		dup := []byte(`{"balances":{"😀":1,"😀":2}}`)
242		if err := checkStrictStrings(dup); err != nil {
243			t.Fatalf("strict scan of duplicate spellings: %v", err)
244		}
245		if err := checkStateStructure(dup); err == nil ||
246			!strings.Contains(err.Error(), "duplicate key") {
247			t.Fatalf("want duplicate key error, got %v", err)
248		}
249	}
250	
251	// TestStrictStateRejectsInvalidStringAnywhere：坏字符串即使出现在本次没有
252	// 查询的另一项提案中，也拒绝读取整份文件，原文件保持原样，查询不给出
253	// 余额、提案或凭据的部分结果。
254	func TestStrictStateRejectsInvalidStringAnywhere(t *testing.T) {
255		dir := t.TempDir()
256		path := filepath.Join(dir, "treasury.json")
257		store, err := InitTreasury(path, 1000)
258		if err != nil {
259			t.Fatal(err)
260		}
261		mustRegister(t, store, "gip-1", 0, "transfer:audits:100")
262		if _, err := store.Execute("gip-1", 0); err != nil {
263			t.Fatal(err)
264		}
265		// gip-2 已登记但未执行：它的动作原文不参与凭据重放，旧逻辑下坏字符
266		// 被改写成 U+FFFD 后整份文件仍会被接受。
267		mustRegister(t, store, "gip-2", 0, "transfer:other:5")
268		store.Close()
269	
270		good, err := os.ReadFile(path)
271		if err != nil {
272			t.Fatal(err)
273		}
274		corruptions := map[string][]byte{
275			"invalid utf8 in unrelated proposal action": bytesReplaceAll(good,
276				[]byte("transfer:other:5"), []byte("transfer:o\xffher:5")),
277			"lone surrogate in unrelated proposal action": bytesReplaceAll(good,
278				[]byte("transfer:other:5"), []byte(`transfer:other:5\uD800`)),
279			"invalid utf8 in unrelated proposal id": bytesReplaceAll(good,
280				[]byte(`"gip-2"`), []byte("\"gip-2\xff\"")),
281		}
282		for name, raw := range corruptions {
283			t.Run(name, func(t *testing.T) {
284				bad := filepath.Join(dir, "strict-"+strings.ReplaceAll(name, " ", "-")+".json")
285				if err := os.WriteFile(bad, raw, 0o600); err != nil {
286					t.Fatal(err)
287				}
288				s, err := Open(bad)
289				if !errors.Is(err, ErrStateCorrupt) {
290					if s != nil {
291						s.Close()
292					}
293					t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
294				}
295				if !strings.Contains(err.Error(), "byte offset") {
296					t.Fatalf("error missing byte offset: %v", err)
297				}
298				// 原文件保持原样，不被重建或覆盖。
299				if got, rerr := os.ReadFile(bad); rerr != nil || !equalBytes(got, raw) {
300					t.Fatalf("corrupt file was modified")
301				}
302				// 对损坏文件初始化同样被拒绝（文件已存在）。
303				if _, err := InitTreasury(bad, 0); !errors.Is(err, ErrTreasuryAlreadyInit) {
304					t.Fatalf("InitTreasury over corrupt err=%v", err)
305				}
306			})
307		}
308	}
309	
310	// TestStrictStateCoherentRenameWithInvalidByte：把账户名在提案动作、凭据
311	// 动作原文、凭据收款账户与余额表键中一致地改成含非法字节的拼写——旧逻辑
312	// 下凭据重放仍然一致，查询却会展示 U+FFFD 账户名；新逻辑必须仅凭字符串
313	// 合法性整份拒绝。
314	func TestStrictStateCoherentRenameWithInvalidByte(t *testing.T) {
315		dir := t.TempDir()
316		path := filepath.Join(dir, "treasury.json")
317		store, err := InitTreasury(path, 1000)
318		if err != nil {
319			t.Fatal(err)
320		}
321		mustRegister(t, store, "gip-1", 0, "transfer:audits:100")
322		if _, err := store.Execute("gip-1", 0); err != nil {
323			t.Fatal(err)
324		}
325		store.Close()
326	
327		good, err := os.ReadFile(path)
328		if err != nil {
329			t.Fatal(err)
330		}
331		raw := bytesReplaceAll(good, []byte("audits"), []byte("\xffudits"))
332		bad := filepath.Join(dir, "coherent-rename.json")
333		if err := os.WriteFile(bad, raw, 0o600); err != nil {
334			t.Fatal(err)
335		}
336		s, err := Open(bad)
337		if !errors.Is(err, ErrStateCorrupt) {
338			if s != nil {
339				s.Close()
340			}
341			t.Fatalf("Open err=%v, want ErrStateCorrupt (replay alone would accept this)", err)
342		}
343		if !strings.Contains(err.Error(), "invalid UTF-8 encoding") {
344			t.Fatalf("error does not identify byte encoding problem: %v", err)
345		}
346	}
347	
348	// TestStrictStatePreservesValidUnicodeRoundTrip：合法 Unicode 文本在编号匹配、
349	// 大小写区分与查询输出中逐字保留；用户明确写出的 U+FFFD 也是合法账户名。
350	func TestStrictStatePreservesValidUnicodeRoundTrip(t *testing.T) {
351		store, path := openTempStore(t, 1000)
352		defer store.Close()
353		mustRegister(t, store, "提案-甲", 0, "transfer:账户甲:100", "transfer:😀:50", "transfer:�:5")
354		if _, err := store.Execute("提案-甲", 0); err != nil {
355			t.Fatalf("execute unicode proposal: %v", err)
356		}
357		// 同内容重试仍按精确匹配判定为幂等。
358		if existed, err := store.Register("提案-甲", 0,
359			[]string{"transfer:账户甲:100", "transfer:😀:50", "transfer:�:5"}); err != nil || !existed {
360			t.Fatalf("idempotent retry existed=%v err=%v", existed, err)
361		}
362		// 大小写区分：Audit 与 audit 互不影响（ASCII 回归）。
363		mustRegister(t, store, "gip-ascii", 0, "transfer:Audit:7")
364		if _, err := store.Execute("gip-ascii", 0); err != nil {
365			t.Fatal(err)
366		}
367	
368		if got, err := store.Balance("账户甲"); err != nil || got != 100 {
369			t.Fatalf("Balance(账户甲)=%d err=%v", got, err)
370		}
371		if got, err := store.Balance("😀"); err != nil || got != 50 {
372			t.Fatalf("Balance(😀)=%d err=%v", got, err)
373		}
374		if got, err := store.Balance("�"); err != nil || got != 5 {
375			t.Fatalf("Balance(U+FFFD)=%d err=%v", got, err)
376		}
377		if got, err := store.Balance("Audit"); err != nil || got != 7 {
378			t.Fatalf("Balance(Audit)=%d err=%v", got, err)
379		}
380		if got, err := store.Balance("audit"); err != nil || got != 0 {
381			t.Fatalf("Balance(audit)=%d err=%v, want 0 (case-sensitive)", got, err)
382		}
383		rec, ok, err := store.Receipt("提案-甲")
384		if err != nil || !ok {
385			t.Fatalf("Receipt ok=%v err=%v", ok, err)
386		}
387		if len(rec.Actions) != 3 || rec.Actions[1].Recipient.Account != "😀" {
388			t.Fatalf("receipt actions not preserved verbatim: %+v", rec.Actions)
389		}
390	
391		// 重新打开：落盘文件中的合法 UTF-8 必须照常读取，查询形状不变。
392		store.Close()
393		reopened, err := Open(path)
394		if err != nil {
395			t.Fatalf("reopen: %v", err)
396		}
397		defer reopened.Close()
398		snap, err := reopened.BalanceSnapshot()
399		if err != nil {
400			t.Fatal(err)
401		}
402		if snap.Treasury != 838 || snap.Balances["账户甲"] != 100 || snap.Balances["�"] != 5 {
403			t.Fatalf("snapshot after reopen lost unicode text: %+v", snap.Balances)
404		}
405	}
406	
407	// TestStrictStateCLIBehavior：命令行沿用既有损坏文件处理方式——原因写
408	// stderr（含字节偏移）、退出码 1、stdout 不输出任何提案、余额或凭据；
409	// 查询的不是坏串所在提案也同样拒绝。
410	func TestStrictStateCLIBehavior(t *testing.T) {
411		binary := buildCLI(t)
412		dir := t.TempDir()
413		state := filepath.Join(dir, "treasury.json")
414		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
415			t.Fatal("init failed")
416		}
417		if _, _, code := runCLI(t, binary, state, "register", "--id", "gip-1",
418			"--timelock", "0", "--action", "transfer:audits:100"); code != 0 {
419			t.Fatal("register gip-1 failed")
420		}
421		if _, _, code := runCLI(t, binary, state, "execute", "--id", "gip-1", "--now", "0"); code != 0 {
422			t.Fatal("execute gip-1 failed")
423		}
424		if _, _, code := runCLI(t, binary, state, "register", "--id", "gip-2",
425			"--timelock", "0", "--action", "transfer:other:5"); code != 0 {
426			t.Fatal("register gip-2 failed")
427		}
428	
429		good, err := os.ReadFile(state)
430		if err != nil {
431			t.Fatal(err)
432		}
433		cases := map[string][]byte{
434			"invalid utf8": bytesReplaceAll(good,
435				[]byte("transfer:other:5"), []byte("transfer:o\xffher:5")),
436			"unpaired surrogate": bytesReplaceAll(good,
437				[]byte("transfer:other:5"), []byte(`transfer:other\uD800:5`)),
438		}
439		for name, raw := range cases {
440			t.Run(name, func(t *testing.T) {
441				bad := filepath.Join(dir, "cli-"+strings.ReplaceAll(name, " ", "-")+".json")
442				if err := os.WriteFile(bad, raw, 0o600); err != nil {
443					t.Fatal(err)
444				}
445				for _, query := range [][]string{
446					{"balances", "--json"},
447					{"proposal", "--id", "gip-1", "--json"},
448					{"proposals"},
449					{"receipts", "--json"},
450				} {
451					stdout, stderr, code := runCLI(t, binary, bad, query...)
452					if code != 1 {
453						t.Fatalf("%v exit=%d stderr=%s", query, code, stderr)
454					}
455					if stdout != "" {
456						t.Fatalf("%v emitted partial stdout:\n%s", query, stdout)
457					}
458					if !strings.Contains(stderr, "treasury state file is corrupt") {
459						t.Fatalf("%v stderr missing corrupt prefix: %s", query, stderr)
460					}
461					if !strings.Contains(stderr, "byte offset") {
462						t.Fatalf("%v stderr missing byte offset: %s", query, stderr)
463					}
464				}
465				if got, rerr := os.ReadFile(bad); rerr != nil || !bytes.Equal(got, raw) {
466					t.Fatalf("corrupt file was modified for %s", name)
467				}
468			})
469		}
470	
471		// 未被污染的文件仍正常查询，输出形状不变。
472		stdout, _, code := runCLI(t, binary, state, "balances", "--account", "audits")
473		if code != 0 || !strings.Contains(stdout, "audits 100") {
474			t.Fatalf("clean file query broken: code=%d stdout=%s", code, stdout)
475		}
476	}
